export const booksApi = {
  search: (q: string, page = 1, size = 20) =>
    api.get<BookSearchResponse>('/api/v1/books', { params: { q, page, size } }),
  getById: (id: string) => api.get<BookDetail>(`/api/v1/books/${id}`),
};

