    api.post<AnswerResponse>(`/api/v1/quizzes/${attemptId}/answer`, { question_id, choice_id }),
  complete: (attemptId: string, email?: string) =>
    api.post<CompleteQuizResponse>(`/api/v1/quizzes/${attemptId}/complete`, { email }),
};

export default api;
